paragraph.math:
$$\begin{array}{l}
  {{{\int{\cos^{3}x}}dx} = {\int\cos^{2}x \cdot \cos xdx = \int{({1 - \sin^{2}x})}\cos xdx}} \\
  {\phantom{{\int{\cos^{3}x}}dx} = {{\int{({1 - u^{2}})}}du = u - \frac{1}{3}u^{3} + C}} \\
  {\phantom{{\int{\cos^{3}x}}dx} = {\sin x - \frac{1}{3}\sin^{3}x + C}}
  \end{array}$$

$$\begin{array}{l}
  {{\int\sec xdx} = {\int\sec x\frac{\sec x + \tan x}{\sec x + \tan x}dx}} \\
  {\phantom{\int\sec xdx} = {\int\frac{\sec^{2}x + \sec x\tan x}{\sec x + \tan x}dx}}
  \end{array}$$

$$\begin{array}{l}
  {{{\int{\tan^{3}x}}dx} = {{\int{\tan x}}\tan^{2}xdx = {\int{\tan x}}{({\sec^{2}x - 1})}dx}} \\
  {\phantom{{\int{\tan^{3}x}}dx} = {{\int{\tan x}}\sec^{2}xdx - {\int{\tan x}}dx}} \\
  {\phantom{{\int{\tan^{3}x}}dx} = {\frac{1}{2}\tan^{2}x - \ln\left| {\sec x} \right| + C}}
  \end{array}$$

$$\begin{array}{rllrll}
  u & = & {\sec x} & {\quad dv} & = & {\sec^{2}xdx} \\
  {du} & = & {\sec x\tan xdx} & {\quad v} & = & {\tan x}
  \end{array}$$

$$\begin{array}{l}
  {{{\int{\sec^{3}x}}dx} = {\sec x\tan x} - {{\int{\sec x}}\tan^{2}xdx}} \\
  {\phantom{{\int{\sec^{3}x}}dx} = {\sec x\tan x} - {{\int{\sec x}}{({\sec^{2}x - 1})}dx}} \\
  {\phantom{{\int{\sec^{3}x}}dx} = {\sec x\tan x} - {{\int{\sec^{3}x}}dx + {\int{\sec x}}dx}}
  \end{array}$$
